<template><BaseLayout><template #body><main><template v-if="!panel"><p>ONE MOTION</p><h1>Hello{{ values.first_name ? ', '+values.first_name : '' }}</h1><p>Your work essentials, all in one place.</p><div class="tiles"><router-link class="tile wide" to="/documents"><FeatherIcon name="folder"/><div><h2>Files</h2><p>Documents and agreements</p></div></router-link><button class="tile wide" :class="{action:actions.length}" @click="panel='Audit & Compliance'"><FeatherIcon name="shield"/><div><h2>Audit &amp; Compliance</h2><p>Actions, checks and review comments</p></div><span v-if="actions.length" class="badge">{{ actions.length }}</span></button><button class="tile" @click="panel='Work'"><FeatherIcon name="briefcase"/><h2>Work</h2><p>Coming soon</p></button><button class="tile" @click="panel='Credentials'"><FeatherIcon name="key"/><h2>Credentials</h2><p>Usernames and passwords</p></button></div></template><template v-else><button class="back" @click="panel=''">‹ Back to Home</button><h1>{{ panel }}</h1><template v-if="panel==='Audit & Compliance'"><h2>Action required</h2><p v-if="loading">Checking outstanding items…</p><p v-if="error">{{ error }}</p><p v-if="!loading&&!error&&!actions.length">No outstanding items found.</p><router-link class="action-row" v-for="item in actions" :key="item.key" :to="item.to"><strong>{{ item.label }}</strong><p>{{ item.reason }} ›</p></router-link><h2 class="audit-title">Audit results</h2><ProfileCompliance :values="values" @open="target=>router.push(target==='agreements'?'/agreements':target==='app'?'/documents':'/profile')"/></template><p v-else-if="panel==='Work'">Coming soon.</p><p v-else>Your work usernames and passwords will appear here once they are connected.</p></template></main></template></BaseLayout></template>
<script setup>
import {computed,ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {FeatherIcon,frappeRequest} from 'frappe-ui'
import BaseLayout from '@/components/BaseLayout.vue'
import ProfileCompliance from '@/components/ProfileCompliance.vue'
import {onboarding,refreshProfile} from '@/data/onboarding'
const router=useRouter(),panel=ref(''),loading=ref(true),error=ref(''),docs=ref([]),agreements=ref([])
const values=computed(()=>onboarding.profile?.values||{})
const actions=computed(()=>{const result=[],labels=Object.fromEntries((onboarding.profile?.sections||[]).flatMap(s=>s.fields||[]).map(f=>[f.key,f.label]));for(const [key,reason] of Object.entries(onboarding.profile?.completion?.errors||{}))result.push({key,label:labels[key]||key.replaceAll('_',' '),reason,to:'/profile'});for(const d of docs.value)if(['missing','rejected','expired'].includes(d.status)&&!['nino_file','utr_file','vat_certificate','eu_licence_declaration','rtw_share_code_file','immigration_share_code_doc','crb_report_document'].includes(d.field))result.push({key:d.field,label:d.label,reason:d.status,to:'/documents'});for(const a of agreements.value)if(a.can_sign&&!a.signed&&['acap_agreement','sba_agrement','dld_agrement','peak_joining_2026'].includes(a.field))result.push({key:a.field,label:a.field==='acap_agreement'?'Associate Compliance Agreement':a.label,reason:'Awaiting signature',to:'/agreements'});return result})
onMounted(async()=>{try{await refreshProfile();const results=await Promise.all(['associate_portal.get_associate_documents','associate_portal.get_associate_agreements','profile_agreement_pack.dld_status','profile_peak_agreement.status'].map(m=>frappeRequest({url:'/api/method/onemotion.api.'+m})));const data=results.map(r=>r?.message??r);docs.value=(Array.isArray(data[0])?data[0]:data[0].groups||[]).flatMap(g=>g.documents||[]);agreements.value=(Array.isArray(data[1])?data[1]:data[1].agreements||[]).filter(a=>a.field!=='dld_agrement');for(const a of data.slice(2))if(a.visible)agreements.value.push(a)}catch{error.value='Some checks could not load. Reopen this page to retry.'}finally{loading.value=false}})
</script>
<style scoped>
main{padding:1.5rem 1rem 6rem;color:#17202b}h1{font-size:1.7rem;margin:.5rem 0}h2{font-size:1rem;margin:0;font-weight:600}p{font-size:.8rem;color:#687586;line-height:1.5;margin:.4rem 0}.tiles{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:24px}.tile{display:flex;flex-direction:column;gap:10px;padding:22px 16px;text-align:left;background:white;color:inherit;border:1px solid #e3e8ee;border-radius:16px;min-width:0}.wide{grid-column:1/-1;flex-direction:row;align-items:center;gap:16px;min-height:96px}.tile svg{width:24px;flex-shrink:0;color:#486885}.action{border-color:#dfaaaa;background:#fff5f4}.badge{margin-left:auto;background:#a61d1d;color:white;border-radius:20px;padding:5px 10px}.back{border:0;background:none;color:#a61d1d;padding:10px 0}.action-row{display:block;padding:16px 0;border-bottom:1px solid #e3e8ee;color:inherit}.action-row strong{font-size:.9rem;font-weight:500}.action-row p{color:#a61d1d}.audit-title{margin-top:24px}button{font:inherit;cursor:pointer}
</style>
